    function maxMintCommission(address token) external view returns (uint256);
    function ratio(address token) external view returns (uint256);
    function getRate(address token) external view returns (uint256);
    function bitcoinChainId() external view returns (bytes32);
    function bascule() external view returns (IGMPBascule);
    function oracle(address token) external view returns (IOracle);
    function mailbox() external view returns (IMailbox);
    function toNativeCommission(address token) external view returns (uint64);
    function nativeToken() external view returns (address);
    function tokenConfig(
        address token
    )
        external
        view
        returns (
            uint256 redeemFee,
            uint256 redeemForBtcMinAmount,
            bool isRedeemEnabled
        );

    function deposit(
        bytes32 tolChainId,
        bytes32 toToken,
        bytes32 recipient,
        uint256 amount
    ) external;

    function deposit(
        address fromAddress,
        address toToken,
        uint256 amount
    ) external;

    function redeemForBtc(
        address fromAddress,
        address fromToken,
        bytes calldata recipient,
        uint256 amount
    ) external;

    function redeem(
        address fromAddress,
        bytes32 tolChainId,
        address fromToken,
        bytes32 toToken,
        bytes32 recipient,
        uint256 amount
    ) external;

    function redeem(
        address fromAddress,
        address fromToken,
        uint256 amount
    ) external;

    function mint(
        bytes calldata rawPayload,
        bytes calldata proof
    ) external returns (address);

    function mintWithFee(
        bytes calldata mintPayload,
        bytes calldata proof,
        bytes calldata feePayload,
        bytes calldata userSignature
    ) external;

    function batchMint(
        bytes[] calldata payload,
        bytes[] calldata proof
    ) external;

    function batchMintWithFee(
        bytes[] calldata mintPayload,
        bytes[] calldata proof,
        bytes[] calldata feePayload,
        bytes[] calldata userSignature
    ) external;

    function calcUnstakeRequestAmount(
        address token,
        bytes calldata scriptPubkey,
        uint256 amount
    ) external view returns (uint256 amountAfterFee, bool isAboveDust);

    function changeRedeemFee(uint256 fee) external;

    function changeRedeemForBtcMinAmount(uint256 minAmount) external;

    function toggleRedeem() external;

    function depositMinAmount(address token) external view returns (uint256);
}

